-- JR Kyushu recurring timetable 2026-03-14 to 2027-02-28, PDF page 4 (index 3).
-- https://www.jrkyushu.co.jp/english/pdf/timetable_20260314_20270228.pdf
-- Date in key is reference revision, NOT a daily run record. No daily formations.
BEGIN;
CREATE TEMP TABLE jr_kyu_p3(key text PRIMARY KEY,name text,dir text) ON COMMIT DROP;
CREATE TEMP TABLE jr_kyu_p3_stops(key text,seq int,station text,clock text,last_stop boolean) ON COMMIT DROP;
DO $$BEGIN
IF (SELECT count(*) FROM jr_kyu_p3)<>35 OR
EXISTS(SELECT 1 FROM jr_kyu_p3 v WHERE (SELECT count(*) FROM jr_kyu_p3_stops s WHERE s.key=v.key)<2)
THEN RAISE EXCEPTION 'JR Kyushu page 3 source missing';END IF;END$$;
SELECT 'KyushuShinkansen','odpt.Calendar:SaturdayHoliday',t.name,
'odpt.Railway:JR-Kyushu.KyushuShinkansen','odpt.RailDirection:'||t.dir,
'odpt.TrainType:JR-Kyushu.Shinkansen',
ARRAY[(SELECT station FROM jr_kyu_p3_stops s WHERE s.key=t.key ORDER BY s.seq DESC LIMIT 1)],
'official-sampled:holiday:https://www.jrkyushu.co.jp/english/pdf/timetable_20260314_20270228.pdf',t.key
FROM jr_kyu_p3 t
WHERE NOT EXISTS (SELECT 1 FROM public.manual_timetable_templates m WHERE m.source_trip_id=t.key AND m.calendar_urn='odpt.Calendar:SaturdayHoliday');
CREATE TEMP TABLE p3_map ON COMMIT DROP AS SELECT t.key,m.id FROM jr_kyu_p3 t
JOIN manual_timetable_templates m ON m.source_trip_id=t.key AND m.line_key='KyushuShinkansen' AND m.calendar_urn='odpt.Calendar:SaturdayHoliday';
DO $$BEGIN IF (SELECT count(*) FROM p3_map)<>35 THEN RAISE EXCEPTION 'P3 template identity mismatch';END IF;END$$;
SELECT m.id,s.seq,CASE WHEN s.last_stop THEN s.station END,
CASE WHEN NOT s.last_stop THEN s.station END,
CASE WHEN s.last_stop THEN s.clock END,
CASE WHEN NOT s.last_stop THEN s.clock END
FROM p3_map m JOIN jr_kyu_p3_stops s ON s.key=m.key
WHERE NOT EXISTS(SELECT 1 FROM manual_timetable_template_stops old WHERE old.template_id=m.id AND old.stop_sequence=s.seq);
SELECT 'source:'||m.id,'odpt.Calendar:SaturdayHoliday',t.train_number,m.id,'source_only','undated_not_current_verified'
FROM p3_map m JOIN manual_timetable_templates t ON t.id=m.id
WHERE NOT EXISTS(SELECT 1 FROM train_timetables old WHERE old.lead_source_template_id=m.id);
SELECT m.id,t.id,0,'primary',0,(SELECT max(stop_sequence) FROM manual_timetable_template_stops s WHERE s.template_id=m.id),0,false
FROM p3_map m JOIN train_timetables t ON t.lead_source_template_id=m.id
WHERE NOT EXISTS(SELECT 1 FROM train_timetable_members old WHERE old.source_template_id=m.id);
DO $$BEGIN IF EXISTS(SELECT 1 FROM p3_map m WHERE (SELECT count(*) FROM manual_timetable_template_stops s WHERE s.template_id=m.id) <>
(SELECT count(*) FROM jr_kyu_p3_stops s WHERE s.key=m.key) OR NOT EXISTS(SELECT 1 FROM train_timetable_members x WHERE x.source_template_id=m.id))
THEN RAISE EXCEPTION 'JR Kyushu P3 stop mapping incomplete';END IF;END$$;
WITH counts AS(SELECT line_key,count(*)::int n,count(distinct calendar_urn)::int cal,count(distinct direction_urn)::int dir,count(*) filter(where source_path like 'official-sampled:%')::int sampled
FROM manual_timetable_templates WHERE line_key='KyushuShinkansen' GROUP BY line_key)
UPDATE published_timetable_coverage_audit a SET template_count=c.n,calendar_count=c.cal,direction_count=c.dir,sampled_count=c.sampled,
issues=(SELECT array_agg(DISTINCT issue ORDER BY issue) FROM unnest(a.issues||ARRAY['KYUSHU_2026_HOLIDAY_REGULAR_P3_IMPORTED']::text[]) issue),checked_at=now()
FROM counts c WHERE a.line_key=c.line_key;
COMMIT;